import React, { useEffect, useState } from 'react'

import { useDispatch, useSelector } from 'react-redux'

import {
    checkTokenValidation,
    getAllOrders,
    logout,
    changeDeliveryStatus
} from '../actions/userActions'

import { CHANGE_DELIVERY_STATUS_RESET } from '../constants'

import { useHistory } from 'react-router-dom'

import { Table, Spinner } from 'react-bootstrap'

import { dateCheck } from '../components/GetDate'

import SearchBarForOrdersPage from '../components/SearchBarForOrdersPage'

import Message from '../components/Message'

import './OrdersListPage.css'


function OrdersListPage() {

    const history = useHistory()

    const dispatch = useDispatch()

    const placeholderValue =
        "Search orders by Customer Name, Address or by Ordered Item"


    // =========================================
    // CURRENT DATE
    // =========================================

    const todays_date =
        dateCheck(
            new Date().toISOString().slice(0, 10)
        )

    const [currentDateInfo] =
        useState(todays_date)

    const [
        idOfchangeDeliveryStatus,
        setIdOfchangeDeliveryStatus
    ] = useState(0)

    const [cloneSearchTerm, setCloneSearchTerm] =
        useState("")


    // =========================================
    // LOGIN REDUCER
    // =========================================

    const userLoginReducer =
        useSelector(
            state => state.userLoginReducer
        )

    const { userInfo } =
        userLoginReducer


    // =========================================
    // GET ALL ORDERS
    // =========================================

    const getAllOrdersReducer =
        useSelector(
            state => state.getAllOrdersReducer
        )

    const {
        orders = [],
        loading: loadingOrders
    } = getAllOrdersReducer


    // =========================================
    // DELIVERY STATUS REDUCER
    // =========================================

    const changeDeliveryStatusReducer =
        useSelector(
            state => state.changeDeliveryStatusReducer
        )

    const {
        success: deliveryStatusChangeSuccess,
        loading: deliveryStatusChangeSpinner
    } = changeDeliveryStatusReducer


    // =========================================
    // TOKEN VALIDATION
    // =========================================

    const checkTokenValidationReducer =
        useSelector(
            state => state.checkTokenValidationReducer
        )

    const {
        error: tokenError
    } = checkTokenValidationReducer


    // =========================================
    // GET ORDERS
    // =========================================

    useEffect(() => {

        if (!userInfo) {

            history.push("/login")

        } else {

            dispatch(
                checkTokenValidation()
            )

            dispatch(
                getAllOrders()
            )

        }

    }, [
        userInfo,
        dispatch,
        history
    ])


    // =========================================
    // SESSION EXPIRED
    // =========================================

    useEffect(() => {

        if (
            userInfo &&
            tokenError ===
            "Request failed with status code 401"
        ) {

            alert(
                "Session expired, please login again."
            )

            dispatch(
                logout()
            )

            history.push("/login")

            window.location.reload()

        }

    }, [
        userInfo,
        tokenError,
        dispatch,
        history
    ])


    // =========================================
    // CHANGE DELIVERY STATUS
    // =========================================

    const changeDeliveryStatusHandler =
        (id, status) => {

            setIdOfchangeDeliveryStatus(id)

            const productData = {

                is_delivered: status,

                delivered_at:
                    status
                        ? currentDateInfo
                        : "Not Delivered"

            }

            dispatch(
                changeDeliveryStatus(
                    id,
                    productData
                )
            )

        }


    // =========================================
    // DELIVERY SUCCESS
    // =========================================

    useEffect(() => {

        if (deliveryStatusChangeSuccess) {

            alert(
                "Delivery status changed successfully"
            )

            dispatch({
                type:
                    CHANGE_DELIVERY_STATUS_RESET
            })

            dispatch(
                getAllOrders()
            )

        }

    }, [
        deliveryStatusChangeSuccess,
        dispatch
    ])


    // =========================================
    // SEARCH
    // =========================================

    const handleSearchTerm = (term) => {

        setCloneSearchTerm(
            term.toLowerCase()
        )

    }


    // =========================================
    // FILTER ORDERS
    // =========================================

    const filteredOrders =
        orders.filter((item) => {

            return (

                (item.name || "")
                    .toLowerCase()
                    .includes(
                        cloneSearchTerm
                    )

                ||

                (item.ordered_item || "")
                    .toLowerCase()
                    .includes(
                        cloneSearchTerm
                    )

                ||

                (item.address || "")
                    .toLowerCase()
                    .includes(
                        cloneSearchTerm
                    )

            )

        })


    // =========================================
    // RETURN
    // =========================================

    return (

        <div className="orders-page">


            {/* =================================
                HEADER
            ================================= */}

            <div className="orders-page-header">

                <div>

                    <h3>
                        📦 Orders
                    </h3>

                    <p>
                        Manage and track customer orders
                    </p>

                </div>

                <div className="orders-count">

                    <strong>
                        {filteredOrders.length}
                    </strong>

                    <span>
                        Orders
                    </span>

                </div>

            </div>


            {/* =================================
                LOADING
            ================================= */}

            {loadingOrders && (

                <div className="orders-loading">

                    <Spinner
                        animation="border"
                        size="sm"
                    />

                    <h5>
                        Getting Orders...
                    </h5>

                </div>

            )}


            {/* =================================
                SEARCH
            ================================= */}

            {userInfo &&
                userInfo.admin && (

                    <div className="orders-search">

                        <SearchBarForOrdersPage

                            handleSearchTerm={
                                handleSearchTerm
                            }

                            placeholderValue={
                                placeholderValue
                            }

                        />

                    </div>

                )
            }


            {/* =================================
                ORDERS TABLE
            ================================= */}

            {filteredOrders.length > 0 ? (

                <div className="orders-table-container">

                    <Table
                        className="orders-table"
                        responsive
                    >

                        <thead>

                            <tr>

                                <th>
                                    Order ID
                                </th>

                                <th>
                                    Customer
                                </th>

                                <th>
                                    Card
                                </th>

                                <th>
                                    Delivery Address
                                </th>

                                <th>
                                    Product
                                </th>

                                <th>
                                    Payment
                                </th>

                                <th>
                                    Paid On
                                </th>

                                <th>
                                    Amount
                                </th>

                                <th>
                                    Delivery
                                </th>

                                <th>
                                    Delivered On
                                </th>

                                {userInfo &&
                                    userInfo.admin && (

                                        <th>
                                            Action
                                        </th>

                                    )
                                }

                            </tr>

                        </thead>


                        <tbody>

                            {filteredOrders.map(
                                (order, idx) => (

                                    <tr
                                        key={
                                            order.id || idx
                                        }
                                    >

                                        {/* ORDER ID */}

                                        <td>

                                            <span className="order-id">

                                                #
                                                {order.id}

                                            </span>

                                        </td>


                                        {/* CUSTOMER */}

                                        <td>

                                            <span className="customer-name">

                                                {order.name}

                                            </span>

                                        </td>


                                        {/* CARD */}

                                        <td>

                                            <span className="card-number">

                                                XXXX XXXX XXXX{" "}

                                                {order.card_number
                                                    ? order.card_number.slice(-4)
                                                    : "----"}

                                            </span>

                                        </td>


                                        {/* ADDRESS */}

                                        <td>

                                            <div className="delivery-address">

                                                {order.address}

                                            </div>

                                        </td>


                                        {/* PRODUCT */}

                                        <td>

                                            <span className="ordered-product">

                                                {order.ordered_item}

                                            </span>

                                        </td>


                                        {/* PAYMENT */}

                                        <td>

                                            {order.paid_status ? (

                                                <span className="status-badge status-paid">

                                                    ✓ Paid

                                                </span>

                                            ) : (

                                                <span className="status-badge status-unpaid">

                                                    ✕ Unpaid

                                                </span>

                                            )}

                                        </td>


                                        {/* PAID DATE */}

                                        <td>

                                            {dateCheck(
                                                order.paid_at
                                            )}

                                        </td>


                                        {/* AMOUNT */}

                                        <td>

                                            <span className="order-price">

                                                ₹
                                                {order.total_price}

                                            </span>

                                        </td>


                                        {/* DELIVERY STATUS */}

                                        <td>

                                            {order.is_delivered ? (

                                                <span className="status-badge status-delivered">

                                                    ✓ Delivered

                                                </span>

                                            ) : (

                                                <span className="status-badge status-pending">

                                                    ⏳ Pending

                                                </span>

                                            )}

                                        </td>


                                        {/* DELIVERED DATE */}

                                        <td>

                                            {order.is_delivered
                                                ? order.delivered_at
                                                : "Not Delivered"}

                                        </td>


                                        {/* ADMIN ACTION */}

                                        {userInfo &&
                                            userInfo.admin && (

                                                <td>

                                                    {order.is_delivered ? (

                                                        <button

                                                            className="btn btn-outline-danger btn-sm delivery-btn"

                                                            onClick={() =>
                                                                changeDeliveryStatusHandler(
                                                                    order.id,
                                                                    false
                                                                )
                                                            }

                                                            disabled={
                                                                deliveryStatusChangeSpinner &&
                                                                idOfchangeDeliveryStatus ===
                                                                order.id
                                                            }

                                                        >

                                                            {deliveryStatusChangeSpinner &&
                                                            idOfchangeDeliveryStatus ===
                                                            order.id ? (

                                                                <Spinner
                                                                    animation="border"
                                                                    size="sm"
                                                                />

                                                            ) : (

                                                                "Mark Undelivered"

                                                            )}

                                                        </button>

                                                    ) : (

                                                        <button

                                                            className="btn btn-outline-primary btn-sm delivery-btn"

                                                            onClick={() =>
                                                                changeDeliveryStatusHandler(
                                                                    order.id,
                                                                    true
                                                                )
                                                            }

                                                            disabled={
                                                                deliveryStatusChangeSpinner &&
                                                                idOfchangeDeliveryStatus ===
                                                                order.id
                                                            }

                                                        >

                                                            {deliveryStatusChangeSpinner &&
                                                            idOfchangeDeliveryStatus ===
                                                            order.id ? (

                                                                <Spinner
                                                                    animation="border"
                                                                    size="sm"
                                                                />

                                                            ) : (

                                                                "Mark Delivered"

                                                            )}

                                                        </button>

                                                    )}

                                                </td>

                                            )
                                        }

                                    </tr>

                                )
                            )}

                        </tbody>

                    </Table>

                </div>

            ) : (

                <div className="no-orders">

                    <div className="no-orders-icon">
                        📦
                    </div>

                    <h5>
                        No Orders Found
                    </h5>

                    <p>
                        There are no orders matching your search.
                    </p>

                </div>

            )}

        </div>

    )

}


export default OrdersListPage
